fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let q=e.path();if e.file_type().unwrap().is_dir(){if !["target-candidate","frozen"].contains(&e.file_name().to_string_lossy().as_ref()){walk(&q,out)}}else if e.file_type().unwrap().is_file(){out.push(q)}}}
fn seal(){let d=Path::new(D);let mut paths=vec![];walk(d,&mut paths);paths.sort();let mut pins=BTreeMap::new();for p in paths{let rel=p.strip_prefix(d).unwrap().display().to_string();if ["SHA256SUMS","artifact-index.json"].contains(&rel.as_str()){continue}pins.insert(rel,hash(p));}save(d.join("artifact-index.json"),&json!(pins));pins.insert("artifact-index.json".into(),hash(d.join("artifact-index.json")));fs::write(d.join("SHA256SUMS"),pins.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();println!("Sealed {} hashes",pins.len());}
fn archive(){let r=Path::new(R);let d=Path::new(D);assert!(!d.exists());let a=read(r.join("analysis.json"));assert_eq!(a["independent_proof_count"],15325);
    for(f,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());}
    let p=&a["pairs"]["1x2-w32/bypass/offset"];
    let mut text=format!("# Whole-query G1 then G2 phases\n\nThe private candidate completes A and fused K/H before B2, using the same full Rayon pool. The primary32 paired ON/OFF ratio is {:.9}, with bounds [{:.9}, {:.9}] and {}/7 wins. The prospective pilot gate is **{}**; production is unchanged.\n\nThe accepted174 source is copied, with one changed branch in lib.rs and a private helper with ordering/panic tests (175 candidate files, 173 original files exact). Reversing the edit and removing the helper recovers all174 originals. OFF preserves the original three-query join expression. Arithmetic, field, grouping, key/solver, forecast and unsupported dispatch stay unchanged. There is no extra pool, lookup table, plan, delay, warmup allocation or new unsafe code.\n\nBoth OFF and ON pass124 unfiltered core and8 prover tests. Native dependencies, including proc macros, are frozen; actual core/field flags and features are audited. OFF/ON share the same candidate executable path and inode, private selector0/1; accept is the retained accepted SDK. Labels offset and bypass mean OFF and ON in the raw artifacts.\n\nSeven fixed rotated/reversed blocks cover primary16/32,16x2/32 and merge54/32, with151 primary or31 other requests after3 primes. Key loading is excluded; solving, fresh proving, SDK verification and serialization are included. No owned compilation/helper/hash/archive/verifier/profile or second benchmark overlaps timing. This is a shared host.\n\n| Cell | Variant | Median ms | CPU ms/request | Median peak MiB | Max peak MiB |\n|---|---|---:|---:|---:|---:|\n",p["median"].as_f64().unwrap(),p["low"].as_f64().unwrap(),p["high"].as_f64().unwrap(),p["wins"],a["gate_passed"]);
    for(k,v)in a["cells"].as_object().unwrap(){let(c,m)=k.split_once('/').unwrap();writeln!(text,"| {c} | {m} | {:.6} | {:.3} | {:.2} | {:.2} |",v["median_ms"].as_f64().unwrap(),v["CPU_ms"].as_f64().unwrap(),v["median_RSS_MiB"].as_f64().unwrap(),v["max_RSS_MiB"].as_f64().unwrap()).unwrap();}
    text.push_str("\nRSS covers the whole process including loading and priming; it is not minimum required RAM.\n\n| Pair | Median ratio | Lower | Upper | Wins | Paired saving ms | Required check |\n|---|---:|---:|---:|---:|---:|---|\n");
    for(k,v)in a["pairs"].as_object().unwrap(){let check=a["checks"].get(k).map(|v|if v==true{"pass"}else{"fail"}).unwrap_or("descriptive");writeln!(text,"| {k} | {:.9} | {:.9} | {:.9} | {}/7 | {:.6} | {check} |",v["median"].as_f64().unwrap(),v["low"].as_f64().unwrap(),v["high"].as_f64().unwrap(),v["wins"],v["paired_saving_ms"].as_f64().unwrap()).unwrap();}
    writeln!(text,"\nFailed checks: `{}`. OFF/accepted calibration is separately recorded for all cells in analysis.json.\n",a["failed_checks"]).unwrap();
    text.push_str("Bounds are the extrema of7 block ratios, nominal98.4375% under independent exchangeable blocks, without familywise guarantees. Primary32 requires upper<1 and at least5/7 wins against both controls plus OFF/accepted bounds withinfactor1.03. Larger ON comparisons require upper<=1.03; physical16 is descriptive. No gain floor, excluded observation, extension, successful-capture repeat or changed threshold. A passing pilot would select further all-eight, clean, portable and resource qualification.\n\nAfter all latency and latency verification,12 FIFO-gated grouped counter captures and6 separate199Hz cycles profiles cover primary16/32 and all three variants. Each counter run has31 requests; each profile251, after3 primes. All diagnostic captures precede their verification/decoding. Diagnostic processes run as root through sudo for perf; latency processes run as the normal user. Priming/loading are excluded by the SDK FIFO control. All PMU events run at least99.9%; all profiles have one sampled PID and zero lost events. These diagnostic times do not enter the latency gate. A single counter/profile per cell does not establish a cache cause or confidence interval. Sampled CPU shares are not removable wall-time fractions.\n\n| Counter process | Event | Count/request | Running % |\n|---|---|---:|---:|\n");
    for(k,v)in a["diagnostics"]["counters"].as_object().unwrap(){for(e,x)in v["events"].as_object().unwrap(){writeln!(text,"| {k} | {e} | {:.3} | {:.2} |",x["per_request"].as_f64().unwrap(),x["running_percent"].as_f64().unwrap()).unwrap();}}
    text.push_str("\n| Profile | Samples | Sampled TIDs | Lost events |\n|---|---:|---:|---:|\n");
    for(k,v)in a["diagnostics"]["profiles"].as_object().unwrap(){writeln!(text,"| {k} | {} | {} | 0 |",v["samples"],v["TIDs"].as_array().unwrap().len()).unwrap();}
    text.push_str("\nAll12 preflight proofs independently verify before84 latency processes. Their84 exports verify afterward; the18 diagnostic exports verify after all diagnostic captures. Total9876 internally verified SDK requests,114 fresh164-byte Gnark exports,228 proof/public members, ledger15211→15325. Closing source, libraries, executables, inputs and helper pins match. Raw perf data stays local with SHA256 receipts; decoded data and complete candidate source are archived.\n\nThe prior [B2 grouping bypass](../2026-10-28-b2-group-only174/README.md) and [global grouping bypass](../2026-10-28-dedup-off174/README.md) remain closed negatives. This tests a whole-query completion barrier; it differs from earlier mixed joint passes and fixed worker partitions. Aeglos's inspected [pinned MSM source](https://github.com/helius-labs/aeglos/blob/0290613e8eeca17a4ce88f6f2d726e8e06a5385d/cpu/msm_impl.hpp#L388) shares passes across jobs; it does not use this G1-then-G2 ordering. There is no new Aeglos timing in this experiment.\n\nNew reference comparisons cover only1x2 and16x2. M5 figures are supplied historical references, not matched-machine measurements.\n\n| Cell | Variant | ms | M5 CPU speedup | M5 Metal speedup |\n|---|---|---:|---:|---:|\n");
    for(k,v)in a["new_reference_comparisons"].as_object().unwrap(){for(m,x)in v["variants"].as_object().unwrap(){writeln!(text,"| {k} | {m} | {:.6} | {:.3}× | {:.3}× |",x["ms"].as_f64().unwrap(),x["CPU_speedup"].as_f64().unwrap(),x["Metal_speedup"].as_f64().unwrap()).unwrap();}}
    text.push_str("\nThe complete accepted-source all-eight table below is inherited. Accepted174/SDK81033 remains unchanged; its primary result is8.366931ms. The original10× CPU goal remains active/unmet,0/8. The historical16x2 adoption bound failure, physical16 uncertainty and baseline-only forced-pressure timeout remain recorded in the [adoption report](../2026-10-28-g2-borrowed-adoption/README.md); this pilot does not overturn them. No54 M5 reference was supplied. There is no new AWS/Aeglos, mobile/ARM/TEE, giant, swap, minimum-RAM or pressure qualification.\n\n| Shape | Accepted ms | M5 CPU ms | CPU speedup | M5 Metal ms | Metal speedup |\n|---|---:|---:|---:|---:|---:|\n");
    for(k,v)in a["inherited_accepted_M5"].as_object().unwrap(){writeln!(text,"| {k} | {:.6} | {} | {:.3}× | {} | {:.3}× |",v["accepted_ms"].as_f64().unwrap(),v["cpu_reference_ms"],v["cpu_speedup"].as_f64().unwrap(),v["metal_reference_ms"],v["metal_speedup"].as_f64().unwrap()).unwrap();}
    text.push_str("\n[Protocol](artifacts/design.md), [all observations and profiles](artifacts/analysis.json), [source audit](artifacts/source-audit.json), [native build](artifacts/native/result.json), [proof inventory](artifacts/proof-inventory.json), [closing pins](artifacts/pins.json).\n");
    let mut paths=vec![];walk(r,&mut paths);paths.sort();let mut local=BTreeMap::new();for from in paths{let rel=from.strip_prefix(r).unwrap();let ext=from.extension().and_then(|x|x.to_str()).unwrap_or("");if ext=="data"{local.insert(from.display().to_string(),hash(&from));continue}if !rel.starts_with("source")&&! ["rs","md","json","jsonl","log","txt","proof","public"].contains(&ext){continue}let to=d.join("artifacts").join(rel);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&from,&to).unwrap();assert_eq!(hash(from),hash(to));}
    save(d.join("artifacts/local-perf-data.json"),&json!(local));
    fs::write(d.join("README.md"),text).unwrap();
    let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-28-g2-borrowed-adoption/artifacts/production-source-manifest.json");let mut source=BTreeMap::new();for f in manifest["source_files_sha256"].as_object().unwrap().keys(){let from=r.join("source").join(f);let to=d.join("artifacts/source").join(f);assert_eq!(hash(&from),hash(to));source.insert(f.clone(),hash(from));}let f="crates/zopro-core/src/query_waves.rs";source.insert(f.into(),hash(r.join("source").join(f)));assert_eq!(source.len(),175);save(d.join("artifacts/complete-source-pins.json"),&json!(source));seal();
}
